<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class CommitteeScheduleItem extends Model{protected $fillable=['committee_id','committee_period_id','committee_function_id','activity_type','title','description','scheduled_date','start_time','end_time','location','modality','responsible_member_id','phva_stage','status','regulation_reference','notes','created_by','updated_by'];protected $casts=['scheduled_date'=>'date'];public function committee(){return $this->belongsTo(Committee::class);}public function period(){return $this->belongsTo(CommitteePeriod::class,'committee_period_id');}public function responsible(){return $this->belongsTo(CommitteeMember::class,'responsible_member_id');}public function changes(){return $this->hasMany(CommitteeScheduleChange::class,'schedule_item_id');}public function meeting(){return $this->hasOne(CommitteeMeeting::class,'schedule_item_id');}}
